function selectionOptions(value,withAll=false){return (withAll?'<option value="all">すべての選抜方式</option>':'')+SELECTION_TYPES.map(t=>`<option value="${t.id}" ${value===t.id?'selected':''}>${esc(t.label)}</option>`).join('');}
function facultyLabel(c){const f=c.faculty||'';if(!f)return '学部未入力';const alias=(seed?.facultyAliases||[]).find(item=>universityKey(item.university)===universityKey(c.university)&&item.faculty===f);return alias?.fullName||(/学部|学群|学域|学環/.test(f)?f:/科学$/.test(f)?f+'部':f+'学部');}
function facultySearchFields(c){return [c.faculty,facultyLabel(c),c.department,c.department?c.department+'学科':''];}
function studentSearchFields(s){return [s.number,pad(s.number),name(s)];}
function guideForChoice(c){const g=getGuide(c?.guideId);return g&&isGuideCompatible(c,g)?g:null;}
function additionalAdmissions(c){return Array.isArray(c?.additionalAdmissions)?c.additionalAdmissions:[];}
function choiceHasSelectionType(c,type){return type==='all'||selectionTypeOf(c)===type||additionalAdmissions(c).some(a=>a.selectionType===type);}
function guideForAdditionalAdmission(c,a){const g=getGuide(a.guideId);return g&&isGuideCompatible({...c,selectionType:a.selectionType,method:a.method},g)?g:null;}
function guidesForChoice(c){return [...new Map([guideForChoice(c),...additionalAdmissions(c).map(a=>guideForAdditionalAdmission(c,a))].filter(Boolean).map(g=>[g.id,g])).values()];}
function scheduleDetail(g,key){const info=seed?.requestedScheduleDetails?.[g.id];if(!info||info.selectedAdmissionVariant!==undefined&&info.selectedAdmissionVariant!==g.selectedAdmissionVariant)return '';const item=info[key];if(!item)return '';const current=key==='exam'?(g.examDateOptions?.length?g.examDateOptions:g.examDates?.length?g.examDates:g.examDate?[g.examDate]:[]):g[key];return JSON.stringify(current)===JSON.stringify(item.value)?item.text:'';}
function admissionScheduleHTML(record,options={}){const g=record||{};const source=key=>{if(!options.sources)return '';const fields=g.fieldSources||{};const examEvidence=g.noIndividualExam?(fields.noIndividualExam||fields.examDate):g.examDateOptions?.length?(fields.examDateOptions||fields.examDate):g.examDates?.length?(fields.examDates||fields.examDate):fields.examDate;const evidence=key==='examDate'?examEvidence:fields[key];return evidence?.url?`<div class="schedule-evidence">${sourceLink(evidence.url,'この日付の出典',evidence.page||'')}</div>`:'';};const date=key=>{const value=g[key],note=scheduleDetail(g,key);return (value?`<time datetime="${esc(value)}">${esc(dateText(value))}</time>`:'<span class="missing">未確認</span>')+(note?`<small class="schedule-note">${esc(note)}</small>`:'')+source(key);};const examNote=scheduleDetail(g,'exam'),exam=examText(g)==='未登録'?'未確認':examText(g),staged=!!(g.secondEnrollmentDeadline||g.finalEnrollmentDeadline);return `<section class="admission-schedule" aria-label="出願・試験・発表・手続の日程">${g.reviewRequired?'<p class="schedule-review">参考日程：選抜方式・募集単位の確認が必要です。</p>':''}<dl><div><dt>出願期間</dt><dd>${date('applicationStart')}<span class="schedule-range">〜</span>${date('applicationEnd')}</dd></div>${g.webRegistrationStart?`<div><dt>Web出願登録開始日</dt><dd>${date('webRegistrationStart')}</dd></div>`:''}${g.webRegistrationEnd?`<div><dt>Web出願登録締切日</dt><dd>${date('webRegistrationEnd')}</dd></div>`:''}<div><dt>試験日</dt><dd>${esc(exam)}${examNote?`<small class="schedule-note">${esc(examNote)}</small>`:''}${source('examDate')}</dd></div><div><dt>合格発表日</dt><dd>${date('resultDate')}</dd></div><div><dt>手続き締切日${staged?'（第一次）':''}</dt><dd>${date('enrollmentDeadline')}</dd></div>${g.secondEnrollmentDeadline?`<div><dt>第二次手続締切日</dt><dd>${date('secondEnrollmentDeadline')}</dd></div>`:''}${g.finalEnrollmentDeadline?`<div><dt>最終手続締切日</dt><dd>${date('finalEnrollmentDeadline')}</dd></div>`:''}</dl><p class="schedule-caption">未確認の日付は公式資料・入試情報で確認してください。</p></section>`;}
function additionalAdmissionsHTML(sid,c){return additionalAdmissions(c).map(a=>{const g=guideForAdditionalAdmission(c,a);return `<section class="additional-admission"><div><span class="pill blue">追加方式：${esc(selectionLabel(a.selectionType))}</span><strong>${esc(a.method||selectionLabel(a.selectionType))}</strong></div>${admissionScheduleHTML(g)}${a.notes?`<p>${esc(a.notes)}</p>`:''}<div class="button-row">${g?`<button class="btn small" data-guide="${esc(g.id)}">追加方式の入試情報・出典</button>`:''}<button class="btn small" data-edit-additional="${esc(sid)}|${c.rank}|${esc(a.id)}">追加方式を編集</button></div></section>`;}).join('');}
function choiceSearchFields(c){const guides=guidesForChoice(c);return [universitySearchText(c.university),c.university,c.rawName,...facultySearchFields(c),c.method,c.schedule,selectionSearchText(selectionTypeOf(c)),...additionalAdmissions(c).flatMap(a=>[a.method,selectionSearchText(a.selectionType)]),...guides.flatMap(g=>[g.method,g.year])];}
function guideSearchFields(g){return [universitySearchText(g.university),g.university,...facultySearchFields(g),g.method,selectionSearchText(selectionTypeOf(g)),g.year,g.sourceName];}
function universityChoices(alias){const key=universityKey(alias);return state.students.flatMap(s=>s.choices.filter(c=>universityKey(c.university)===key).map(c=>({s,c}))).sort((a,b)=>a.s.number-b.s.number||a.c.rank-b.c.rank);}
function universityGuides(alias){const key=universityKey(alias);return state.guidelines.filter(g=>universityKey(g.university)===key);}
function universityCatalog(){const universities=new Map(officialCatalog().map(u=>[universityKey(u.university),u]));for(const item of [...allChoices(),...state.guidelines]){const key=universityKey(item.university);if(key&&!universities.has(key))universities.set(key,{university:item.university,fullName:item.university,availability:'unavailable',documentTitle:'手動で登録された大学・学校'});}return [...universities.values()];}
function selectionSources(alias){const key=universityKey(alias);return (seed?.selectionSources||[]).filter(u=>universityKey(u.university)===key).flatMap(u=>u.routes||[]);}
function refreshSearchResults(){if($('#guide-results'))updateGuideResults();if($('#student-results')){$('#student-results').innerHTML=studentsTable();bindActions($('#student-results'));}}
function mergeImportedStudents(importedStudents,previousStudents){return importedStudents.map(s=>{const prev=previousStudents.find(x=>x.number===s.number);const choices=s.choices.map(c=>{const old=prev?.choices.find(x=>x.rank===c.rank&&x.code&&x.code===c.code);return {...c,...(old?.guideId?{guideId:old.guideId}:{}),...(old?.selectionType?{selectionType:old.selectionType}:{}),...(old?.officialLinkDismissed?{officialLinkDismissed:true}:{}),...(old?.additionalAdmissions?{additionalAdmissions:structuredClone(old.additionalAdmissions)}:{}),notes:old?.notes||c.notes};});for(const old of prev?.choices||[])if(old.requestedAdmissionUpdateId&&!choices.some(c=>c.rank===old.rank))choices.push(structuredClone(old));return {...s,name:prev?.name||s.name,choices:choices.sort((a,b)=>a.rank-b.rank)};});}
function filteredStudents(){return state.students.filter(s=>{const choices=s.choices.filter(c=>selectionFilter==='all'||choiceHasSelectionType(c,selectionFilter));return (choices.length?choices.some(c=>matchesSearch(query,[...studentSearchFields(s),...choiceSearchFields(c)])):selectionFilter==='all'&&matchesSearch(query,studentSearchFields(s)))&&(filter!=='unlinked'||s.choices.some(c=>!guideForChoice(c)))&&(filter!=='blank'||s.choices.length<8);});}
function studentCell(s){return `<div class="student-cell"><span class="student-avatar">${pad(s.number)}</span><div><strong>${esc(name(s))}</strong><small>3A ・ 出席番号 ${pad(s.number)}</small></div></div>`;}
function school(c){if(!c)return '<span class="muted">—</span>';return `<div class="school-name">${esc(c.university||c.rawName)}</div><div class="school-detail">${esc([facultyLabel(c),c.department,c.schedule,c.method].filter(Boolean).join(' / '))}</div><div class="school-detail">受験予定：${esc([selectionLabel(selectionTypeOf(c)),...additionalAdmissions(c).map(a=>selectionLabel(a.selectionType))].join(' / '))}</div><div class="school-schedules">${admissionScheduleHTML(guideForChoice(c))}${additionalAdmissions(c).map(a=>`<div class="school-additional-schedule"><span class="pill blue">追加：${esc(a.method||selectionLabel(a.selectionType))}</span>${admissionScheduleHTML(guideForAdditionalAdmission(c,a))}</div>`).join('')}</div>`;}
function studentsTable(){const students=filteredStudents();return `<div class="table-wrap"><table class="${tableMode==='all'?'rank-table':'summary-table'}"><thead><tr><th>生徒</th>${tableMode==='all'?Array.from({length:8},(_,i)=>`<th>第${i+1}志望</th>`).join(''):'<th>第1志望</th><th>登録志望</th><th>募集要項</th><th></th>'}</tr></thead><tbody>${students.map(s=>`<tr><td><button data-student="${esc(s.id)}" aria-label="${esc(name(s))}の志望校を開く">${studentCell(s)}</button></td>${tableMode==='all'?Array.from({length:8},(_,i)=>{const c=s.choices.find(c=>c.rank===i+1);return `<td><button class="rank-cell" data-choice="${esc(s.id)}|${i+1}">${school(c)}${c?`<div style="margin-top:7px"><span class="pill ${guideForChoice(c)?publicationTone(guideForChoice(c)):'gray'}">${guideForChoice(c)?publicationLabel(guideForChoice(c)):'要項未登録'}</span></div>`:''}</button></td>`;}).join(''):`<td>${school(s.choices.find(c=>c.rank===1))}</td><td><span style="font-size:16px">${s.choices.length}</span><small> / 8 校</small></td><td><span class="pill ${s.choices.length&&s.choices.every(c=>guideForChoice(c))?'green':'amber'}">${s.choices.filter(c=>guideForChoice(c)).length} / ${s.choices.length} ひも付け済み</span></td><td><button class="row-open" data-student="${esc(s.id)}">志望校を見る ${icon('arrow')}</button></td>`}</tr>`).join('')}</tbody></table>${students.length?'':`<div class="empty">該当する生徒がいません。</div>`}</div><div class="table-foot"><span>${students.length} / 42 人を表示</span><span>${tableMode==='all'?'横にスクロールして第8志望まで確認できます':'生徒を開いて8志望を確認 →'}</span></div>`;}
function officialCatalog(){return state.officialCatalog||seed?.officialCatalog||[];}
function publicationLabel(g){if(!g)return '要項未登録';if(g.reviewRequired)return '方式の確認が必要';if(g.publicationStatus==='published_guideline')return '公式募集要項';if(g.publicationStatus==='official_schedule')return '公式日程・概要';if(g.publicationStatus==='not_yet_published')return '2027要項未確認';if(g.publicationStatus==='unavailable')return '資料未確認';return '確認・登録済み';}
function publicationTone(g){return g?.reviewRequired?'amber':g?.publicationStatus==='official_schedule'?'blue':['not_yet_published','unavailable'].includes(g?.publicationStatus)?'gray':'green';}
function examText(g){if(g.noIndividualExam)return '個別試験なし';if(g.examDateOptions?.length)return g.examDateOptions.map(dateText).join('、')+'（選択可能日）';if(g.examDates?.length)return g.examDates.map(dateText).join('、');return dateText(g.examDate);}
function sourceLink(url,label,page=''){const safe=safeURL(url);if(!safe)return '';const target=page&&/^\d+$/.test(String(page))&&/\.pdf(?:\?|$)/i.test(safe)?safe.split('#')[0]+'#page='+page:safe;return `<a class="btn small" href="${esc(target)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;}
function officialBanner(){const catalog=officialCatalog();if(!catalog.length)return '';const published=catalog.filter(x=>x.availability==='published_guideline').length;const partial=catalog.filter(x=>x.availability==='official_schedule').length;return `<div class="notice"><span class="notice-icon">${icon('file')}</span><div><h3>2027年度の公式入試情報を登録しました</h3><p>57大学を確認：募集要項 ${published}大学 / 公式日程・概要 ${partial}大学 / 公表待ち・資料未確認 ${catalog.length-published-partial}大学。確認日 ${esc(seed?.officialCheckedAt||'2026-10-18')}。変更・訂正は公式ページも確認してください。</p></div><button class="btn" data-go-official>公式掲載状況</button></div>`;}


function universityFacultySummary(entries,limit=4){
 const groups=new Map();
 for(const {s,c} of entries){const label=facultyLabel(c);if(!groups.has(label))groups.set(label,{count:0,students:new Set()});const group=groups.get(label);group.count++;group.students.add(s.id);}
 return [...groups].sort((a,b)=>b[1].count-a[1].count||a[0].localeCompare(b[0],'ja')).slice(0,limit).map(([label,group])=>`${label} ${group.students.size}人・${group.count}志望`).join(' / ')+(groups.size>limit?` / ほか${groups.size-limit}学部`:'');
}
function catalogCard(u){const entries=universityChoices(u.university),people=new Set(entries.map(({s})=>s.id)).size,guides=universityGuides(u.university).filter(g=>selectionFilter==='all'||selectionTypeOf(g)===selectionFilter),routes=selectionSources(u.university).filter(r=>selectionFilter==='all'||r.selectionType===selectionFilter);return `<article class="guide-card"><div class="guide-card-top"><h3>${esc(u.fullName||u.university)}</h3><span class="pill ${u.availability==='published_guideline'?'green':u.availability==='official_schedule'?'blue':'amber'}">${esc(publicationLabel({publicationStatus:u.availability}))}</span></div><div class="university-summary"><strong>${people} 人</strong><span> / ${entries.length} 志望</span></div><p>${esc(universityFacultySummary(entries)||'この大学への志望は未登録です')}</p><p>${esc(u.documentTitle||'2027年度の公開状況')}</p><p class="catalog-schedule-intro">学部・選抜方式ごとの日程です。大学共通の日付ではありません。</p><div class="catalog-schedules" tabindex="0" role="region" aria-label="${esc(u.fullName||u.university)}の学部・方式別日程">${guides.map(g=>`<section class="catalog-schedule-unit"><h4>${esc([facultyLabel(g),g.department].filter(Boolean).join(' / '))}</h4><p>${esc(selectionLabel(selectionTypeOf(g)))} / ${esc(g.method||'方式未確認')}</p>${admissionScheduleHTML(g)}<button class="btn small" data-guide="${esc(g.id)}">入試情報・出典</button></section>`).join('')}${routes.map(r=>`<section class="catalog-schedule-unit"><h4>${esc(selectionLabel(r.selectionType))}の公式案内</h4><p>${esc(r.title||'対象学部は公式資料で確認')}</p>${admissionScheduleHTML(r)}${sourceLink(r.url,'公式資料を確認')}</section>`).join('')}${guides.length||routes.length?'':admissionScheduleHTML(null)}</div><div class="card-bottom" style="margin-top:18px"><span class="pill">入試情報 ${guides.length} 件 / 公式案内 ${routes.length} 件</span><button class="row-open" data-official-university="${esc(u.university)}">志望生徒・入試情報 ${icon('arrow')}</button></div></article>`;}
function openOfficialUniversity(alias){
 const key=universityKey(alias),u=universityCatalog().find(item=>universityKey(item.university)===key);
 if(!u)return;
 const entries=universityChoices(u.university),people=new Set(entries.map(({s})=>s.id)).size,faculties=[...new Set(entries.map(({c})=>facultyLabel(c)))].sort((a,b)=>a.localeCompare(b,'ja'));
 const urls=[...new Set([u.guidelineUrl,...(u.sourceUrls||[]),u.officialUrl].filter(Boolean))];
 universityDetail={alias:u.university,query:'',faculty:'all',type:'all'};
 drawer(u.fullName||u.university,'2027年度 / 3Aの志望状況と選抜方式別の入試情報',`<div class="university-summary"><strong>${people} 人</strong><span> / ${entries.length} 志望</span><p>同じ生徒の複数学部・複数方式も、志望順位ごとに表示します。</p></div><p class="footer-note">${esc(universityFacultySummary(entries,20))}</p><h3 class="section-title">志望生徒・学部を確認</h3><div class="university-filters"><div class="search">${icon('search')}<input id="university-student-search" aria-label="この大学を志望する生徒・学部・学科を検索" placeholder="出席番号・氏名・学部・学科で検索" value=""></div><label class="field"><span>学部</span><select id="university-faculty" aria-label="学部で絞り込み"><option value="all">すべての学部</option>${faculties.map(faculty=>`<option value="${esc(faculty)}">${esc(faculty)}</option>`).join('')}</select></label><label class="field"><span>選抜方式</span><select id="university-selection" aria-label="選抜方式で絞り込み">${selectionOptions('all',true)}</select></label></div><p class="footer-note">氏名・学部の検索は志望一覧に適用します。選抜方式の絞り込みは、下の入試情報にも適用します。CSVで確定できない受験予定は「未確認」のまま確認・設定してください。</p><div id="university-results"></div><h3 class="section-title">大学の公式資料・公開状況</h3><div class="info-box ${u.availability==='published_guideline'?'':'warning-box'}"><strong>${esc(publicationLabel({publicationStatus:u.availability}))}</strong><br>${esc(u.availabilityNote||'大学の公式ページで対象年度・学部・方式を確認してください。')}<br>確認日：${esc(u.checkedAt||seed?.officialCheckedAt||'未記録')}</div><p style="font-size:12px;line-height:1.9;margin:14px 0">${esc(u.documentTitle||'公式入試情報')}</p><div class="button-row">${urls.map((url,i)=>sourceLink(url,i===0&&u.guidelineUrl===url?'公式資料を開く':'公式ページ '+(i+1))).join('')||'<span class="muted">公式ページは未登録です。</span>'}</div><p class="footer-note">公式資料のリンクを開くにはインターネット接続が必要です。空欄の日付は未確認です。学部・方式が異なる日程を代用していません。</p>`);
 bindSearchInput($('#university-student-search'),value=>{if(!universityDetail)return;universityDetail.query=value;updateUniversityResults();});
 $('#university-faculty').onchange=e=>{universityDetail.faculty=e.target.value;updateUniversityResults();};
 $('#university-selection').onchange=e=>{universityDetail.type=e.target.value;updateUniversityResults();};
 updateUniversityResults();
}
function universityChoiceRows(entries){
 return entries.map(({s,c})=>{
  const g=guideForChoice(c),type=selectionTypeOf(c),explicit=typeof c.selectionType==='string'&&c.selectionType!=='unknown';
  const csvType=selectionTypeOf({...c,selectionType:undefined});
  const csvMethod=[c.schedule,c.method].filter(Boolean).join(' / ');
  return `<tr><td><button class="university-student-link" data-student="${esc(s.id)}"><strong>${pad(s.number)}　${esc(name(s))}</strong></button></td><td><span class="pill">第${c.rank}志望</span></td><td><strong>${esc(facultyLabel(c))}</strong><small>${esc(c.department||'学科・専攻未入力')}</small></td><td><select data-plan-choice="${esc(s.id)}|${c.rank}" aria-label="${esc(name(s))}の第${c.rank}志望の受験予定方式">${selectionOptions(type)}</select><small>${explicit?'受験予定として設定済み':type==='unknown'?'受験予定は未確認':'CSV表記から分類・受験予定は要確認'}</small>${admissionScheduleHTML(g)}${additionalAdmissionsHTML(s.id,c)}</td><td><span>${esc(csvMethod||'方式の記載なし')}</span><small>CSV分類：${esc(selectionLabel(csvType))}</small></td><td><div class="button-row"><button class="btn small" data-choice="${esc(s.id)}|${c.rank}">${g?'入試情報':'資料を確認'}</button><button class="btn small" data-edit-choice-global="${esc(s.id)}|${c.rank}">志望を編集</button></div><small>${g?(type==='unknown'?'登録資料にひも付け済み・受験予定方式は要確認':'対応する方式の資料にひも付け済み'):'対応する資料は未ひも付け'}</small></td></tr>`;
 }).join('');
}
function selectionSourceCard(route){
 const labels={published:'2027年度の公式資料',overview:'公式の選抜概要',school_only:'校内で推薦条件を確認',year_unconfirmed:'2027年度は未確認'};
 const status=labels[route.status]||'公式資料';
 return `<article class="selection-source-card"><div class="guide-card-top"><h4>${esc(route.title||selectionLabel(route.selectionType)+'の公式資料')}</h4><span class="pill ${route.status==='published'?'green':route.status==='overview'?'blue':'amber'}">${esc(status)}</span></div>${route.note?`<p>${esc(route.note)}</p>`:''}${admissionScheduleHTML(route)}${route.status==='school_only'?'<p class="footer-note">指定校の推薦枠・対象学部・校別の出願条件は、高校に配布された資料と校内の担当者に確認してください。</p>':''}<div class="button-row">${sourceLink(route.url,'公式資料を開く')}</div><p class="footer-note">${route.year==='2027'?'2027年度 / ':''}確認日：${esc(route.checkedAt||'未記録')}</p></article>`;
}
function universityGuideCard(g){return `<article class="selection-source-card"><div class="guide-card-top"><h4>${esc([facultyLabel(g),g.department].filter(Boolean).join(' / '))}</h4><span class="pill ${publicationTone(g)}">${esc(publicationLabel(g))}</span></div><p>${esc(g.year||'年度未確認')}年度 / ${esc(g.method||selectionLabel(selectionTypeOf(g)))}</p>${admissionScheduleHTML(g)}<div class="button-row" style="margin-top:12px"><button class="btn small" data-guide="${esc(g.id)}">日程・出典を確認 ${icon('arrow')}</button></div></article>`;}
function universitySelectionSections(entries){
 const detail=universityDetail,guides=universityGuides(detail.alias),routes=selectionSources(detail.alias);
 const order=['comprehensive','designated','recommendation','general','other'];
 if(guides.some(g=>selectionTypeOf(g)==='unknown'))order.push('unknown');
 const types=detail.type==='all'?order:order.includes(detail.type)?[detail.type]:['unknown'];
 return types.map(type=>{
  const matchingEntries=entries.filter(({c})=>choiceHasSelectionType(c,type)),people=new Set(matchingEntries.map(({s})=>s.id)).size;
  const matchingGuides=guides.filter(g=>selectionTypeOf(g)===type&&(detail.faculty==='all'||!g.faculty||facultyLabel(g)===detail.faculty));
  const matchingRoutes=routes.filter(route=>route.selectionType===type);
  return `<section class="selection-section"><div class="panel-head"><div><h3>${esc(selectionLabel(type))}</h3><p>${people} 人 / ${matchingEntries.length} 志望</p></div><button class="btn small" data-new-university-guide="${esc(detail.alias)}|${type}">${icon('plus')}この方式の資料を追加</button></div>${type==='designated'?'<p class="info-box warning-box">指定校推薦の推薦枠・対象学部・出願資格・校内締切は、高校に配布された資料で確認してください。公開されている一般・公募制推薦の要項では代用できません。</p>':''}${matchingRoutes.map(selectionSourceCard).join('')}${matchingGuides.map(universityGuideCard).join('')}${!matchingRoutes.length&&!matchingGuides.length?admissionScheduleHTML(null)+'<p class="info-box">この方式の2027年度要項・日程は未登録です。</p>':!matchingGuides.length?'<p class="footer-note">この方式の個別日程は未登録です。上の公式資料で対象年度・学部・方式を確認してください。</p>':''}</section>`;
 }).join('');
}
function updateUniversityResults(){
 const results=$('#university-results');if(!universityDetail||!results)return;
 const detail=universityDetail,all=universityChoices(detail.alias),facultyEntries=all.filter(({c})=>detail.faculty==='all'||facultyLabel(c)===detail.faculty);
 const entries=facultyEntries.filter(({s,c})=>(detail.type==='all'||choiceHasSelectionType(c,detail.type))&&matchesSearch(detail.query,[...studentSearchFields(s),...choiceSearchFields(c)]));
 const people=new Set(entries.map(({s})=>s.id)).size;
 results.innerHTML=`<div class="route-counts" aria-live="polite"><strong>${people} 人 / ${entries.length} 志望を表示</strong><span>大学全体：${new Set(all.map(({s})=>s.id)).size} 人 / ${all.length} 志望</span></div><div class="table-wrap"><table class="university-student-table"><thead><tr><th>番号・氏名</th><th>志望順位</th><th>学部・学科</th><th>主方式・追加方式</th><th>元の方式・日程区分</th><th>資料・編集</th></tr></thead><tbody>${universityChoiceRows(entries)}</tbody></table>${entries.length?'':'<div class="empty">条件に合う志望がありません。検索語・学部・選抜方式を変更してください。</div>'}</div><p class="footer-note">受験予定方式を変更すると、以前の方式の要項ひも付けを解除します。元CSVの表記は保持します。同じ大学でも学部・年度・選抜方式により日程が異なります。</p><h3 class="section-title">選抜方式別の公式資料・登録日程</h3>${universitySelectionSections(facultyEntries)}`;
 bindActions(results);
 results.querySelectorAll('[data-plan-choice]').forEach(select=>select.onchange=guard(async()=>{
  const [sid,rank]=select.dataset.planChoice.split('|'),value=select.value;
  try{commit(next=>{const choice=next.students.find(s=>s.id===sid)?.choices.find(c=>c.rank===Number(rank));if(choice)applyChoiceEdit(choice,{selectionType:value});});refreshSearchResults();}
  finally{updateUniversityResults();}
 }));
}

function eventsForGuide(g){if(g.reviewRequired)return [];const events=Object.entries({...dateLabels,...additionalDateLabels}).filter(([key])=>key!=='examDate'&&g[key]).map(([key,label])=>({date:g[key],key,label,g}));if(!g.noIndividualExam){const options=g.examDateOptions?.length?g.examDateOptions:[];const dates=options.length?options:(g.examDates?.length?g.examDates:(g.examDate?[g.examDate]:[]));for(const date of dates)events.push({date,key:'examDate',label:options.length?'試験日（選択可能日）':'試験日',g});}return events;}
function guidelineMatches(){const list=state.guidelines.filter(g=>(selectionFilter==='all'||selectionTypeOf(g)===selectionFilter)&&matchesSearch(query,guideSearchFields(g)));const catalog=universityCatalog().filter(u=>{const base=[universitySearchText(u.university),u.university,u.fullName];const guides=universityGuides(u.university).filter(g=>selectionFilter==='all'||selectionTypeOf(g)===selectionFilter);const choices=universityChoices(u.university).filter(({c})=>selectionFilter==='all'||choiceHasSelectionType(c,selectionFilter));const sources=selectionSources(u.university).filter(r=>selectionFilter==='all'||r.selectionType===selectionFilter);return (selectionFilter==='all'&&matchesSearch(query,[...base,u.documentTitle]))||guides.some(g=>matchesSearch(query,[...base,...guideSearchFields(g)]))||choices.some(({s,c})=>matchesSearch(query,[...base,...studentSearchFields(s),...choiceSearchFields(c)]))||sources.some(r=>matchesSearch(query,[...base,r.title,selectionSearchText(r.selectionType),r.year]));});const routes=universityCatalog().flatMap(u=>selectionSources(u.university).map(route=>({...route,university:u.university}))).filter(route=>(selectionFilter==='all'||route.selectionType===selectionFilter)&&matchesSearch(query,[universitySearchText(route.university),route.title,selectionSearchText(route.selectionType),route.year]));const officialMode=guideMode==='official';return {list,catalog,routes,officialMode};}
function sourceResultCard(route){const u=universityCatalog().find(u=>universityKey(u.university)===universityKey(route.university));return `<section class="guide-card"><div class="guide-card-top"><h3>${esc(u?.fullName||route.university)}</h3><span class="pill blue">${esc(selectionLabel(route.selectionType))}</span></div>${selectionSourceCard(route)}<p>個別の日程は未登録です。対象学部・方式の公式資料を確認してください。</p><div class="button-row" style="margin-top:12px"><button class="btn small" data-official-university="${esc(route.university)}">志望生徒・方式別の資料を見る ${icon('arrow')}</button></div></section>`;}
function guidelineCount(matches){return matches.officialMode?matches.catalog.length+'大学':matches.list.length+'件'+(matches.routes?.length?' / 公式案内 '+matches.routes.length+'件':'');}
function guidelineResults({list,catalog,officialMode,routes=[]}){return `${officialMode?`<div class="library-grid">${catalog.map(catalogCard).join('')}</div>`:`<div class="library-grid" id="guide-list">${list.map(g=>`<article class="guide-card"><div class="guide-card-top"><h3>${esc(g.university)}</h3><span class="pill ${publicationTone(g)}">${esc(publicationLabel(g))}</span></div><p>${esc(g.year)}年度 / ${esc([facultyLabel(g),g.department].filter(Boolean).join(' / '))}</p><p><span class="pill blue">${esc(selectionLabel(selectionTypeOf(g)))}</span> ${esc(g.method)}</p>${admissionScheduleHTML(g)}<div class="card-bottom"><span class="pill">${allChoices().filter(c=>guidesForChoice(c).some(linked=>linked.id===g.id)).length} 志望にひも付け</span><button class="row-open" data-guide="${esc(g.id)}">入試情報 ${icon('arrow')}</button></div></article>`).join('')}${routes.map(sourceResultCard).join('')}</div>`}${(officialMode?catalog.length:list.length+routes.length)?'':empty('file','該当する入試情報がありません','検索条件を変えるか、対象の選抜方式の募集要項を追加してください。',btn('募集要項を追加','new-guide','primary','plus'))}`;}
function guidelinesView(){const matches=guidelineMatches();const {list,catalog,officialMode}=matches;return head('UNIVERSITIES & ADMISSIONS','大学・募集要項','大学から志望生徒・学部・選抜方式を確認できます。正式名称、略称、かな読みでも検索できます。',btn('募集要項を追加','new-guide','primary','plus'))+`<div class="filters" style="padding-left:0"><div class="search">${icon('search')}<input id="guide-search" aria-label="大学・学部・選抜方式を検索" placeholder="例：ちゅうきょう / 中京大学 経済" value="${esc(query)}"></div><select id="guide-selection" aria-label="選抜方式で絞り込み">${selectionOptions(selectionFilter,true)}</select><div class="segmented"><button data-guide-mode="official" class="${officialMode?'active':''}">大学から探す</button><button data-guide-mode="records" class="${!officialMode?'active':''}">要項・日程から探す</button></div><span id="guide-count" class="muted" style="font-size:11px" role="status" aria-live="polite">${guidelineCount(matches)}</span></div><p class="search-help">空白で区切ると、すべての条件に一致する志望・資料を検索します。例：「名古屋大学 情報」「中京 経済 一般」</p><div id="guide-results">${guidelineResults(matches)}</div>`;}
function updateGuideResults(){const matches=guidelineMatches(),results=$('#guide-results');$('#guide-count').textContent=guidelineCount(matches);results.innerHTML=guidelineResults(matches);bindActions(results);}
function empty(ico,title,text,actions=''){return `<div class="panel empty"><div class="empty-icon">${icon(ico)}</div><h3>${title}</h3><p>${text}</p>${actions}</div>`;}
function calendarView(){const student=studentId?byId(studentId):null;const ids=student?student.choices.flatMap(guidesForChoice).map(g=>g.id):null;const events=state.guidelines.filter(g=>(!ids||ids.includes(g.id))&&(selectionFilter==='all'||selectionTypeOf(g)===selectionFilter)).flatMap(eventsForGuide).filter(e=>filter==='all'||(filter==='upcoming'&&e.date>=today())||e.key===filter).sort((a,b)=>a.date.localeCompare(b.date));let month='';return head('ADMISSION SCHEDULE','入試日程','公式資料で確認できた日付を表示。方式要確認の参考日程は除外し、選択可能日を区別しています。',btn('募集要項を追加','new-guide','primary','plus'))+`<div class="filters" style="padding-left:0"><select id="calendar-student" aria-label="生徒ごとの日程"><option value="">学級全体の入試情報</option>${state.students.map(s=>`<option value="${esc(s.id)}" ${studentId===s.id?'selected':''}>${esc(name(s))}</option>`).join('')}</select><select id="calendar-selection" aria-label="日程の選抜方式">${selectionOptions(selectionFilter,true)}</select><select id="calendar-kind" aria-label="日程の種類"><option value="all">すべての日程</option><option value="upcoming" ${filter==='upcoming'?'selected':''}>今日以降の日程</option>${Object.entries({...dateLabels,...additionalDateLabels}).map(([key,label])=>`<option value="${key}" ${filter===key?'selected':''}>${label}</option>`).join('')}</select><span class="muted" style="font-size:11px">${events.length} 件</span></div>${events.map(e=>{const newMonth=e.date.slice(0,7)!==month;month=e.date.slice(0,7);const associated=state.students.filter(s=>s.choices.some(c=>guidesForChoice(c).some(g=>g.id===e.g.id)));return `${newMonth?`<h2 class="event-month">${month.replace('-','年 ')}月</h2>`:''}<article class="event"><div class="event-date">${Number(e.date.slice(8))}<small>${new Intl.DateTimeFormat('ja-JP',{weekday:'short',timeZone:'Asia/Tokyo'}).format(new Date(e.date+'T12:00:00+09:00'))}曜日</small></div><div class="event-description"><h3>${esc(e.g.university)} <span class="pill ${e.key.endsWith('End')||e.key.toLowerCase().includes('deadline')?'amber':'green'}">${e.label}</span></h3><p>${esc([e.g.faculty,e.g.department,e.g.method].filter(Boolean).join(' / '))} ・ ${associated.length} 人${e.date<today()?' ・ 終了した日程':''}</p><p><span class="pill ${publicationTone(e.g)}">${esc(publicationLabel(e.g))}</span></p></div><button class="btn small" data-guide="${esc(e.g.id)}">入試情報 ${icon('arrow')}</button></article>`;}).join('')||empty('calendar','表示できる日程はまだありません','公式資料で未確認の日付は表示しません。募集要項を追加するか、公式掲載状況をご確認ください。')}`;}
function dataView(){return head('DATA & BACKUP','データ管理','編集した情報と募集要項を保存・移行できます。')+`<div class="info-box">保存先はこのブラウザです。端末・ブラウザを変えた場合やブラウザのデータを削除した場合は、バックアップから復元してください。複数端末での自動同期はありません。</div><div class="settings-grid"><section class="settings-card"><h2>バックアップ</h2><p>生徒、8志望、入試日程、取り込んだPDFを1つのJSONファイルに保存します。定期的な保存をおすすめします。</p><div class="button-row">${btn('すべて保存','export-backup','primary','download')}${btn('バックアップから復元','restore-backup','','upload')}</div></section><section class="settings-card"><h2>志望校CSV</h2><p>元の2行見出しのCSVに対応。42人を確認して更新します。同じ出席番号・志望順位・募集単位コードのひも付けと、入力した氏名を引き継ぎます。</p><div class="button-row">${btn('CSVを更新','import-csv','','upload')}${btn('現在の志望校をCSV保存','export-csv','','download')}</div></section><section class="settings-card"><h2>現在のデータ</h2><p>生徒 ${state.students.length} 人 / 志望 ${allChoices().length} 件<br>募集要項 ${state.guidelines.length} 件<br>最終保存：${state.updatedAt?esc(new Date(state.updatedAt).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo'})):'初期データの読み込み'}</p><span class="pill green">公開用の空の初期データを使用</span></section><section class="settings-card"><h2>募集要項の読み込みについて</h2><p>文字情報を含むPDF、TXT、本文の貼り付けに対応しています。抽出候補は確認してから登録します。画像だけのPDFは、OCR済みの本文を貼り付けるか手入力してください。</p>${btn('募集要項を登録','new-guide','','plus')}</section></div>`;}
function bindSearchInput(input,onSearch){
 if(!input)return;
 let composing=false,lastValue=input.value;
 const update=()=>{const value=input.value;if(value===lastValue)return;lastValue=value;onSearch(value);};
 input.oncompositionstart=()=>{composing=true;};
 input.oncompositionend=()=>{composing=false;update();};
 input.oninput=e=>{if(!composing&&!e.isComposing)update();};
}
function bindShell(){
 document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{view=el.dataset.view;query='';filter='all';selectionFilter='all';studentId=null;shell();});
 bindActions($('#app'));
 bindSearchInput($('#student-search'),value=>{query=value;refreshSearchResults();});
 const sf=$('#student-filter');if(sf)sf.onchange=()=>{filter=sf.value;refreshSearchResults();};
 const st=$('#student-selection');if(st)st.onchange=()=>{selectionFilter=st.value;refreshSearchResults();};
 document.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>{tableMode=el.dataset.mode;shell();});
 bindSearchInput($('#guide-search'),value=>{query=value;updateGuideResults();});
 const gt=$('#guide-selection');if(gt)gt.onchange=()=>{selectionFilter=gt.value;updateGuideResults();};
 if($('#calendar-student'))$('#calendar-student').onchange=e=>{studentId=e.target.value||null;shell();};
 if($('#calendar-kind'))$('#calendar-kind').onchange=e=>{filter=e.target.value;shell();};
 if($('#calendar-selection'))$('#calendar-selection').onchange=e=>{selectionFilter=e.target.value;shell();};
}
function bindActions(root){
 root.querySelectorAll('[data-official-university]').forEach(el=>el.onclick=()=>openOfficialUniversity(el.dataset.officialUniversity));
 root.querySelectorAll('[data-go-official]').forEach(el=>el.onclick=()=>{view='guidelines';query='';guideMode='official';shell();});
 root.querySelectorAll('[data-guide-mode]').forEach(el=>el.onclick=()=>{guideMode=el.dataset.guideMode;shell();});
 root.querySelectorAll('[data-action]').forEach(el=>el.onclick=guard(async()=>{const a=el.dataset.action;if(a==='new-guide')openGuideEditor();if(a==='retry-requested'){persist(mergeOfficialSeed(state,seed));shell();notify('指定された追加方式を再確認しました');}if(a==='import-csv')$('#csv-file').click();if(a==='export-backup'){el.disabled=true;notify('PDFを含めてバックアップを作成しています…');try{download(JSON.stringify(await exportBackup(state)),`3A進路ノート_${today()}.json`,'application/json');notify('バックアップを保存しました');}finally{el.disabled=false;}}if(a==='restore-backup')$('#backup-file').click();if(a==='export-csv')exportCSV();}));
 root.querySelectorAll('[data-student]').forEach(el=>el.onclick=()=>openStudent(el.dataset.student));
 root.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>{const [sid,rank]=el.dataset.choice.split('|');const c=getChoice(sid,rank);c?openAdmission(sid,rank):openChoiceEditor(sid,rank);});
 root.querySelectorAll('[data-edit-additional]').forEach(el=>el.onclick=()=>{const [sid,rank,aid]=el.dataset.editAdditional.split('|');openAdditionalAdmissionEditor(sid,Number(rank),aid||null);});
 root.querySelectorAll('[data-guide-variant]').forEach(el=>el.onclick=guard(async()=>{const [gid,index]=el.dataset.guideVariant.split('|');selectGuideVariant(gid,Number(index));}));
 root.querySelectorAll('[data-guide]').forEach(el=>el.onclick=()=>openGuide(el.dataset.guide));
 root.querySelectorAll('[data-edit-choice-global]').forEach(el=>el.onclick=()=>{const [sid,rank]=el.dataset.editChoiceGlobal.split('|');openChoiceEditor(sid,rank);});
 root.querySelectorAll('[data-new-university-guide]').forEach(el=>el.onclick=()=>{const [university,selectionType]=el.dataset.newUniversityGuide.split('|');openGuideEditor(null,null,{university,selectionType,year:'2027',method:selectionLabel(selectionType)});});
}
function drawer(title,subtitle,body,footer='',avatar=''){if(!$('#overlay').innerHTML)focusReturn=document.activeElement;$('#overlay').innerHTML=`<div class="drawer-backdrop"><section class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="drawer-head"><div class="drawer-title">${avatar?`<span class="student-avatar large">${esc(avatar)}</span>`:''}<div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div></div><button class="close" id="close-drawer" aria-label="閉じる">${icon('close')}</button></div><div class="drawer-body">${body}</div>${footer?`<div class="form-actions">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';$('#close-drawer').onclick=()=>closeDrawer();$('#overlay .drawer-backdrop').onclick=e=>{if(e.target.classList.contains('drawer-backdrop'))closeDrawer();};bindActions($('#overlay'));$('#close-drawer').focus();}
function closeDrawer(){if(uploadDraft?.busy||uploadDraft?.saving){notify('資料の読み込みが終わるまでお待ちください。');return;}if($('#guide-form')&&uploadDraft?.dirty&&!confirm('入力中の募集要項を閉じますか？未保存の内容は破棄されます。'))return;$('#overlay').innerHTML='';document.body.style.overflow='';uploadDraft=null;focusReturn?.focus?.();}
function openStudent(sid){const s=byId(sid);if(!s)return;drawer(name(s),'3A ・ 出席番号 '+pad(s.number)+' ・ '+s.choices.length+' / 8 志望を登録',`<div class="profile-bar"><p>大学名を開くと志望生徒を一覧できます。受験予定の方式は「編集」で設定してください。</p><div class="button-row"><button class="btn small" id="rename-student">${icon('edit')}氏名を編集</button><button class="btn small" id="print-student">印刷</button></div></div><div class="choices">${Array.from({length:8},(_,i)=>{const c=s.choices.find(c=>c.rank===i+1);if(!c)return `<article class="choice-card blank"><span class="rank-label">第 <b>${i+1}</b> 志望</span><p>まだ登録されていません</p><button class="btn small" data-edit-choice="${i+1}">${icon('plus')}志望校を追加</button></article>`;const g=guideForChoice(c);return `<article class="choice-card ${i===0?'first':''}"><div class="choice-top"><span class="rank-label">第 <b>${i+1}</b> 志望</span><span class="pill ${g?publicationTone(g):'gray'}">${g?publicationLabel(g):'要項未登録'}</span></div><h3><button class="university-link" data-official-university="${esc(c.university)}">${esc(c.university||c.rawName)} ↗</button></h3><p>${esc([c.faculty,c.department].filter(Boolean).join(' / '))||'学部・学科未入力'}</p><p><span class="pill blue">受験予定：${esc(selectionLabel(selectionTypeOf(c)))}</span>${!c.selectionType&&selectionTypeOf(c)!=='unknown'?'<small> CSVから分類・予定は要確認</small>':''}</p><p>CSV方式：${esc([c.schedule,c.method].filter(Boolean).join(' / '))||'記載なし'}</p>${admissionScheduleHTML(g)}${additionalAdmissionsHTML(sid,c)}<div class="choice-actions"><button class="btn small ${g?'primary':''}" data-choice="${esc(sid)}|${i+1}">${icon('calendar')}入試情報</button><button class="btn link" data-edit-choice="${i+1}">${icon('edit')}編集</button><button class="btn link" data-edit-additional="${esc(sid)}|${i+1}">${icon('plus')}方式を追加</button></div></article>`;}).join('')}</div>`, '',pad(s.number));
 $('#rename-student').onclick=()=>{drawer('氏名を編集','出席番号 '+pad(s.number),`<form id="name-form">${field('氏名','name',s.name)}<p class="footer-note">元のCSVには氏名がないため、初期表示は出席番号です。</p></form>`,`<button class="btn" id="back-student">戻る</button><button class="btn primary" type="submit" form="name-form">保存</button>`);$('#back-student').onclick=()=>openStudent(sid);$('#name-form').onsubmit=guard(async e=>{e.preventDefault();commit(st=>st.students.find(x=>x.id===sid).name=new FormData(e.target).get('name').trim());shell();openStudent(sid);notify('氏名を保存しました');});};
 $('#print-student').onclick=()=>window.print();
 document.querySelectorAll('[data-edit-choice]').forEach(el=>el.onclick=()=>openChoiceEditor(sid,el.dataset.editChoice));
}
function openAdditionalAdmissionEditor(sid,rank,aid=null){const c=getChoice(sid,rank);if(!c)return;const a=additionalAdmissions(c).find(a=>a.id===aid)||{selectionType:'unknown',method:'',guideId:'',notes:''};drawer(aid?'追加方式を編集':'受験方式を追加',name(byId(sid))+' / 第'+rank+'志望 / '+c.university,`<form id="additional-form"><div class="form-grid"><label class="field full"><span>追加する選抜方式 *</span><select name="selectionType" required>${selectionOptions(a.selectionType)}</select></label>${field('方式の詳細','method',a.method,'text',true)}<label class="field full"><span>対応する募集要項</span><select name="guideId" id="additional-guide"></select><small>大学・学部・型・年度を確認して選択してください。空欄のまま方式だけ追加することもできます。</small></label><label class="field full"><span>メモ</span><textarea name="notes" rows="3">${esc(a.notes)}</textarea></label></div><p class="footer-note">現在の方式・志望順位は維持し、追加方式を別に管理します。</p></form>`,`<button class="btn" id="back-student">戻る</button>${aid?'<button class="btn danger" id="delete-additional">この追加方式を削除</button>':''}<button class="btn primary" type="submit" form="additional-form">保存</button>`);const form=$('#additional-form');const updateGuides=()=>{const selected=form.elements.guideId.value||a.guideId;const type=form.elements.selectionType.value;const list=universityGuides(c.university).filter(g=>isGuideCompatible({...c,selectionType:type},g));form.elements.guideId.innerHTML='<option value="">未ひも付け</option>'+list.map(g=>`<option value="${esc(g.id)}" ${selected===g.id?'selected':''}>${esc([g.year,facultyLabel(g),g.department,g.method].filter(Boolean).join(' / '))}</option>`).join('');};form.elements.selectionType.onchange=updateGuides;updateGuides();$('#back-student').onclick=()=>openStudent(sid);form.onsubmit=guard(async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));Object.keys(data).forEach(k=>data[k]=String(data[k]).trim());if(data.selectionType==='unknown')throw Error('追加する選抜方式を選択してください。');if(data.guideId&&!isGuideCompatible({...c,selectionType:data.selectionType},getGuide(data.guideId)))throw Error('追加方式と募集要項の方式が一致していません。');commit(st=>{const choice=st.students.find(s=>s.id===sid).choices.find(c=>c.rank===Number(rank));const current=(choice.additionalAdmissions||[]).find(a=>a.id===aid);if(current)Object.assign(current,data);else{choice.additionalAdmissions=choice.additionalAdmissions||[];choice.additionalAdmissions.push({...data,id:crypto.randomUUID()});}});shell();openStudent(sid);notify('追加方式を保存しました');});if($('#delete-additional'))$('#delete-additional').onclick=guard(async()=>{if(!confirm('この追加方式を削除しますか？元の志望校と方式は残ります。'))return;commit(st=>{const choice=st.students.find(s=>s.id===sid).choices.find(c=>c.rank===Number(rank));choice.additionalAdmissions=additionalAdmissions(choice).filter(a=>a.id!==aid);});shell();openStudent(sid);notify('追加方式を削除しました');});}
function openChoiceEditor(sid,rank){rank=Number(rank);const s=byId(sid),c=getChoice(sid,rank)||{};drawer(`第${rank}志望を編集`,name(s),`<form id="choice-form"><div class="form-grid">${field('大学・学校名 *','university',c.university)}${field('学部','faculty',c.faculty)}${field('学科・専攻','department',c.department)}<label class="field"><span>受験予定の選抜方式</span><select name="selectionType">${selectionOptions(selectionTypeOf(c))}</select><small>方式を変更すると以前の要項ひも付けを解除します。</small></label>${field('方式の詳細・CSV方式','method',c.method)}${field('日程区分','schedule',c.schedule)}${field('募集単位コード','code',c.code)}<label class="field full"><span>原文の募集単位名</span><input name="rawName" value="${esc(c.rawName)}"><small>CSVに記載された募集単位名です。略記は原文のまま保持しています。</small></label><label class="field full"><span>メモ</span><textarea name="notes" rows="3">${esc(c.notes)}</textarea></label></div></form>`,`<button class="btn" id="back-student">戻る</button>${c.rank?'<button class="btn danger" id="delete-choice">この志望を削除</button>':''}<button class="btn primary" form="choice-form" type="submit">保存</button>`);$('#back-student').onclick=()=>openStudent(sid);$('#choice-form [name=university]').required=true;$('#choice-form').onsubmit=guard(async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));Object.keys(data).forEach(key=>data[key]=String(data[key]).trim());commit(st=>{const ss=st.students.find(x=>x.id===sid);const next=applyChoiceEdit({...c,id:c.id||`${sid}-${rank}`,rank},data);ss.choices=ss.choices.filter(x=>x.rank!==rank).concat(next).sort((a,b)=>a.rank-b.rank);});shell();openStudent(sid);notify('志望校を保存しました');});if($('#delete-choice'))$('#delete-choice').onclick=guard(async()=>{if(!confirm(`第${rank}志望を削除しますか？後の志望順位は繰り上げません。`))return;commit(st=>st.students.find(x=>x.id===sid).choices=st.students.find(x=>x.id===sid).choices.filter(x=>x.rank!==rank));shell();openStudent(sid);notify('志望校を削除しました');});}
function openAdmission(sid,rank){const c=getChoice(sid,rank);if(!c)return;const linked=guideForChoice(c);if(linked){openGuide(linked.id,{sid,rank});return;}const list=universityGuides(c.university).filter(g=>isGuideCompatible(c,g));drawer(`第${rank}志望の入試情報`,name(byId(sid))+' / '+c.university,`<div class="info-box">${esc([facultyLabel(c),c.department].filter(Boolean).join(' / '))}<br>受験予定：${esc(selectionLabel(selectionTypeOf(c)))}<br>この志望に対応する募集要項はまだひも付いていません。</div><div class="button-row" style="margin-bottom:18px"><button class="btn" data-official-university="${esc(c.university)}">大学の志望生徒・方式別資料を見る</button></div><h3 class="section-title">受験予定の方式に対応する登録済み要項</h3>${list.map(g=>`<article class="guide-card" style="margin-bottom:12px"><div class="guide-card-top"><h3>${esc(g.year)}年度 / ${esc(selectionLabel(selectionTypeOf(g)))}</h3></div><p>${esc([facultyLabel(g),g.department,g.method].filter(Boolean).join(' / '))}</p>${admissionScheduleHTML(g)}<div class="button-row" style="margin-top:14px"><button class="btn small" data-guide="${esc(g.id)}">詳細を確認</button><button class="btn primary small" data-link-guide="${esc(g.id)}">この要項をひも付け</button></div></article>`).join('')||admissionScheduleHTML(null)+'<p class="muted" style="font-size:12px;margin-bottom:25px">この方式の要項・日程は未登録です。大学の公式資料を確認するか、要項を追加してください。</p>'}<div class="button-row"><button class="btn primary" id="new-for-choice">${icon('plus')}この方式の募集要項を登録</button><button class="btn" data-edit-choice-global="${esc(sid)}|${rank}">受験予定の方式を編集</button><button class="btn" id="back-student">生徒に戻る</button></div><p class="footer-note">選抜方式が異なる要項は候補に含めません。予定が未確認の場合は、学部・年度・方式を照合してからひも付けてください。</p>`);$('#new-for-choice').onclick=()=>openGuideEditor(null,{sid,rank},{university:c.university,faculty:c.faculty,department:c.department,year:'2027',selectionType:selectionTypeOf(c),method:selectionTypeOf(c)==='unknown'?'':selectionLabel(selectionTypeOf(c))});$('#back-student').onclick=()=>openStudent(sid);document.querySelectorAll('[data-link-guide]').forEach(el=>el.onclick=guard(async()=>{const gid=el.dataset.linkGuide,g=getGuide(gid);if(!g||!isGuideCompatible(getChoice(sid,rank),g))throw Error('受験予定の選抜方式と要項の方式が一致していません。');commit(st=>{const choice=st.students.find(s=>s.id===sid).choices.find(c=>c.rank===Number(rank));choice.guideId=gid;choice.officialLinkDismissed=false;if(selectionTypeOf(choice)==='unknown'&&selectionTypeOf(g)!=='unknown')choice.selectionType=selectionTypeOf(g);});shell();openGuide(gid,{sid,rank});notify('募集要項をひも付けました');}));}
function guideVariantsHTML(g){if(!g.admissionVariants?.length)return '';return `<h3 class="section-title">総合型の候補と日程</h3><div class="info-box ${g.reviewRequired?'warning-box':''}">${g.reviewRequired?'型が未確定です。下の候補から受験した型を選んでください。確定するまで、この要項の日程はカレンダーへ登録しません。':'受験予定の型を選択済みです。必要な場合は下から変更できます。'}</div>${g.admissionVariants.map((v,i)=>`<section class="admission-variant"><h3>${esc(v.method)}</h3>${admissionScheduleHTML(v,{sources:true})}<p class="footer-note">${esc(v.notes||'')}</p><button class="btn small ${g.selectedAdmissionVariant===i?'':'primary'}" data-guide-variant="${esc(g.id)}|${i}">${g.selectedAdmissionVariant===i?'この型を選択済み':'この型に確定する'}</button></section>`).join('')}`;}
function selectGuideVariant(gid,index){const g=getGuide(gid),variant=g?.admissionVariants?.[index];if(!variant)return;commit(st=>{const guide=st.guidelines.find(g=>g.id===gid);for(const key of Object.keys({...dateLabels,...additionalDateLabels}))guide[key]=variant[key]||'';guide.method=variant.method;guide.examDateOptions=variant.examDateOptions||[];guide.examDates=variant.examDates||[];guide.fieldSources=variant.fieldSources||{};guide.sourceUrl=variant.sourceUrl||guide.sourceUrl;guide.sourceName=variant.sourceName||guide.sourceName;guide.sourcePage=variant.sourceUrl?.match(/#page=(\d+)/)?.[1]||variant.sourcePage||'';guide.notes=variant.notes||'';guide.reviewRequired=false;guide.variantSelectionRequired=false;guide.selectedAdmissionVariant=index;guide.userModifiedAt=new Date().toISOString();guide.availabilityNote='生徒の受験予定の型を選択済みです。日程と原文の条件を確認してください。';for(const student of st.students)for(const choice of student.choices)for(const route of additionalAdmissions(choice))if(route.guideId===gid){route.method=variant.method;if(route.notes==='総合型の型は未確定です。候補から選択してください。')route.notes='受験予定の型を選択済みです。';}});shell();openGuide(gid);notify('総合型の型を確定しました');}
function openGuide(gid,context=null){const g=getGuide(gid);if(!g)return;const linked=state.students.filter(s=>s.choices.some(c=>guidesForChoice(c).some(g=>g.id===gid)));const pdfUrl=g.pdfUrl||(/\.pdf(?:\?|$)/i.test(g.sourceUrl||'')?g.sourceUrl:'');drawer(g.university,`${g.year}年度 / ${[g.faculty,g.department,g.method].filter(Boolean).join(' / ')}`,`<div class="button-row"><span class="pill ${publicationTone(g)}">${esc(publicationLabel(g))}</span><span class="pill">${linked.length} 人 / ${allChoices().filter(c=>guidesForChoice(c).some(g=>g.id===gid)).length} 志望にひも付け</span></div>${g.sourceKind==='official'?`<div class="info-box ${g.publicationStatus==='published_guideline'&&!g.reviewRequired?'':'warning-box'}" style="margin-top:16px">${esc(g.availabilityNote||(g.publicationStatus==='official_schedule'?'募集要項本体が公表される前の公式日程・概要を含みます。対象方式と最終要項を確認してください。':'公式資料から確認できた項目を登録しています。'))}<br>空欄は未確認です。選択可能な試験日は、まだ生徒の受験確定日ではありません。</div>`:''}<div class="detail-grid"><div class="detail-item"><span>選抜方式</span><strong>${esc(selectionLabel(selectionTypeOf(g)))} / ${esc(g.method)||'詳細未登録'}</strong></div></div>${admissionScheduleHTML(g,{sources:true})}${guideVariantsHTML(g)}<section class="source-block"><h3>根拠となる公式資料・募集要項</h3><p>${esc(g.sourceName||'資料名未入力')}${g.sourcePage?' / '+esc(g.sourcePage)+' ページ':''}</p><div class="button-row" style="margin-top:12px">${sourceLink(g.sourceUrl,'出典を開く',g.sourcePage)}${pdfUrl&&pdfUrl!==g.sourceUrl?sourceLink(pdfUrl,'公式PDFを開く'):''}${g.documentId?'<button class="btn small" id="open-pdf">保存したPDFを開く ↗</button>':''}${g.sourceKind==='official'?`<button class="btn small" data-official-university="${esc(g.university)}">この大学の公開状況</button>`:''}</div>${g.excerpt?`<p style="max-height:250px;overflow:auto">${esc(g.excerpt)}</p>`:''}${g.notes?`<h3 style="margin-top:18px">出願条件・締切時刻・追加の日程</h3><p>${esc(g.notes)}</p>`:''}<p style="font-size:10px">${g.sourceKind==='official'?'公式資料の確認日':'確認日'}：${g.checkedAt?esc(g.checkedAt):g.verifiedAt?esc(new Date(g.verifiedAt).toLocaleDateString('ja-JP',{timeZone:'Asia/Tokyo'})):'未記録'}${g.userModifiedAt?' / 手動編集あり':''}</p></section>${linked.length?`<h3 class="section-title">ひも付いている生徒</h3><div class="button-row">${linked.map(s=>`<button class="btn small" data-student="${esc(s.id)}">${esc(name(s))}</button>`).join('')}</div>`:''}`,`<button class="btn" id="guide-back">${context?'生徒に戻る':'閉じる'}</button>${context?'<button class="btn" id="unlink-guide">ひも付けを解除</button>':''}<button class="btn primary" id="edit-guide">${icon('edit')}入試情報を編集</button>`);$('#guide-back').onclick=()=>context?openStudent(context.sid):closeDrawer();$('#edit-guide').onclick=()=>openGuideEditor(gid,context);if($('#unlink-guide'))$('#unlink-guide').onclick=guard(async()=>{commit(st=>{const choice=st.students.find(s=>s.id===context.sid).choices.find(c=>c.rank===Number(context.rank));delete choice.guideId;choice.officialLinkDismissed=true;});shell();openAdmission(context.sid,context.rank);notify('ひも付けを解除しました');});if($('#open-pdf'))$('#open-pdf').onclick=guard(async()=>{const doc=await getDocument(g.documentId);if(!doc)throw Error('保存したPDFが見つかりません。公式資料のリンクからも確認できます。');const url=URL.createObjectURL(doc.blob);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),600000);});}

function openGuideEditor(gid=null,context=null,preset={}){const g=getGuide(gid)||preset,c=context?getChoice(context.sid,context.rank):{};uploadDraft={dirty:false,pages:[],file:null,documentId:g.documentId||null};drawer(gid?'募集要項を編集':'募集要項を登録','資料から候補を抽出し、年度・選抜方式・日程を確認して登録します。',`<form id="guide-form"><h3 class="section-title">1. 資料を読み込む <small>PDF / TXT / 本文貼り付け</small></h3><div class="upload-box"><h3>${icon('upload')} 募集要項を選択</h3><p>文字情報を含むPDFに対応。画像PDFはOCR済み本文を下に貼り付けてください。<br>ファイルはこの端末で処理します。${g.documentId?'登録済みPDFは、新しいPDFを選ぶまで引き継ぎます。':''}</p><input id="guideline-file" type="file" accept=".pdf,.txt,text/plain,application/pdf" aria-label="募集要項ファイルを選択"></div><label class="field full" style="margin-top:15px"><span>本文・確認したいページのテキスト</span><textarea id="guideline-text" rows="5" placeholder="出願期間、試験日、合格発表、入学手続などが記載された箇所を貼り付け">${esc(g.excerpt)}</textarea><small>複数の方式がある資料は、対象方式のページ・本文に絞って抽出してください。</small></label><div class="button-row" style="margin-top:12px"><button class="btn" type="button" id="extract-candidates">${icon('search')}日程の候補を抽出</button></div><div class="extract-status" id="extract-status" role="status"></div><div class="candidate-list" id="candidates"></div><h3 class="section-title">2. 募集単位と年度を確認</h3><div class="form-grid">${field('大学・学校名 *','university',g.university||c?.university)}${field('入試年度 *','year',g.year||'2027','number',false,'例：2027年度。個々の日付の年は日付欄で確認します。')}${field('学部','faculty',g.faculty||c?.faculty)}${field('学科・専攻','department',g.department||c?.department)}<label class="field full"><span>選抜方式の区分 *</span><select name="selectionType" required>${selectionOptions(selectionTypeOf(g))}</select><small>総合型・指定校・公募制・一般を区別して登録します。</small></label>${field('選抜方式の詳細・日程区分 *','method',g.method||[c?.schedule,c?.method].filter(Boolean).join(' / '),'text',true)}<h3 class="section-title field full">3. 日程を確認・登録 <small>原文と照合して入力</small></h3>${Object.entries({...dateLabels,...additionalDateLabels}).map(([key,label])=>field(label,key,g[key],'date')).join('')}<label class="field full"><span>出願条件・時刻・追加の日程・メモ</span><textarea name="notes" rows="3" placeholder="郵送必着／消印有効、Web登録と書類提出の別、試験時刻、手続の段階など">${esc(g.notes)}</textarea><small>試験が複数日ある場合は方式別の要項を分けるか、残りの日程をここに記録してください。</small></label>${field('資料名','sourceName',g.sourceName,'text',true)}${field('根拠ページ','sourcePage',g.sourcePage)}${field('公式ページURL','sourceUrl',g.sourceUrl,'url')}<label class="field full"><span><input type="checkbox" name="confirmed" required> 対象年度・学部・選抜方式と、原文の日程を確認しました *</span><small>自動抽出の候補は確定情報ではありません。日付の年、締切時刻、必着・消印有効なども確認してください。</small></label></div></form>`,`<button class="btn" id="cancel-guide">戻る</button>${gid?'<button class="btn danger" id="delete-guide">削除</button>':''}<button class="btn primary" type="submit" form="guide-form" id="save-guide">確認して保存${context?'・ひも付け':''}</button>`);
 const form=$('#guide-form');['university','year','method'].forEach(k=>form.elements[k].required=true);
 form.oninput=e=>{uploadDraft.dirty=true;if(e.target.id==='guideline-text')uploadDraft.pages=[];};
 $('#cancel-guide').onclick=()=>{if(uploadDraft?.busy||uploadDraft?.saving)return;if(uploadDraft.dirty&&!confirm('入力内容を破棄して戻りますか？'))return;uploadDraft=null;gid?openGuide(gid,context):context?openStudent(context.sid):closeDrawer();};
 $('#guideline-file').onchange=guard(async e=>{const file=e.target.files[0];if(!file)return;if(file.size>50*1024*1024)throw Error('50MB以下のファイルを選択してください。');const status=$('#extract-status');status.textContent='資料を読み込んでいます…';$('#extract-candidates').disabled=true;$('#save-guide').disabled=true;uploadDraft.dirty=true;uploadDraft.busy=true;uploadDraft.file=null;uploadDraft.pages=[];e.target.disabled=true;try{if(file.name.toLowerCase().endsWith('.pdf')){const pdfjs=await __loadEmbeddedPDF();const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),cMapUrl:'embedded:cmaps/',cMapPacked:true,standardFontDataUrl:'embedded:standard-fonts/',BinaryDataFactory:__EmbeddedPDFBinaryDataFactory,useWorkerFetch:false,useWasm:false,isEvalSupported:false}).promise;if(pdf.numPages>500){await pdf.destroy();throw Error('500ページを超えるPDFは、対象ページを分割して読み込んでください。');}const pages=[];for(let p=1;p<=pdf.numPages;p++){status.textContent=`PDFを読み込み中 ${p} / ${pdf.numPages} ページ`;const page=await pdf.getPage(p),content=await page.getTextContent();let text='',lastY=null;for(const item of content.items){if(!('str'in item))continue;const y=item.transform?.[5];if(lastY!==null&&Math.abs(y-lastY)>3)text+='\n';text+=item.str+(item.hasEOL?'\n':' ');lastY=y;}pages.push({page:p,text});page.cleanup();}await pdf.destroy();uploadDraft.pages=pages;uploadDraft.file=file;$('#guideline-text').value=pages.map(p=>`【${p.page}ページ】\n${p.text}`).join('\n\n');status.textContent=pages.some(p=>p.text.replace(/\s/g,'').length>20)?`${pages.length}ページを読み込みました。対象の方式を確認し、候補を抽出してください。`:'文字情報が見つかりません。画像PDFは、OCR済みの本文を貼り付けるか日程を手入力してください。';}else{$('#guideline-text').value=await file.text();uploadDraft.pages=[];uploadDraft.file=null;uploadDraft.documentId=null;status.textContent='本文を読み込みました。候補を抽出してください。';}form.elements.sourceName.value=file.name;}catch(err){status.textContent='読み込みに失敗しました。本文の貼り付け・手入力も利用できます。';throw err;}finally{uploadDraft.busy=false;e.target.disabled=false;$('#extract-candidates').disabled=false;$('#save-guide').disabled=false;}});
 $('#extract-candidates').onclick=()=>{const text=$('#guideline-text').value;const candidates=extractCandidates(text,uploadDraft.pages);$('#extract-status').textContent=candidates.length?`${candidates.length}件の候補が見つかりました。対象方式の原文と照合して「採用」してください。`:'候補を特定できませんでした。原文を確認して日程欄に入力してください。';$('#candidates').innerHTML=candidates.slice(0,100).map((ca,i)=>`<div class="candidate"><label>${esc(ca.label)}<small>${esc(ca.value)}${ca.page?' / p.'+esc(ca.page):''}</small></label><p>${esc(ca.excerpt)}</p><button type="button" class="btn small" data-candidate="${i}">採用</button></div>`).join('');document.querySelectorAll('[data-candidate]').forEach(el=>el.onclick=()=>{const ca=candidates[Number(el.dataset.candidate)],input=form.elements[ca.field];if(!input)return;const val=ca.field==='method'?ca.value:normalizeDate(ca.value);if(!val){notify('原文の年が明確ではありません。日付欄で西暦を含めて手入力してください。');input.focus();return;}input.value=val;if(ca.page)form.elements.sourcePage.value=String(ca.page);uploadDraft.dirty=true;el.textContent='採用済み';el.disabled=true;notify(`${ca.label}を入力しました。原文と確認してください。`);});};
 form.onsubmit=guard(async e=>{e.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));delete data.confirmed;Object.keys(data).forEach(k=>data[k]=String(data[k]).trim());if(data.applicationStart&&data.applicationEnd&&data.applicationStart>data.applicationEnd)throw Error('出願開始日は出願締切日より前の日付にしてください。');if(data.selectionType==='unknown')throw Error('募集要項の選抜方式の区分を確認して選択してください。');if(context&&!isGuideCompatible(getChoice(context.sid,context.rank),data))throw Error('この志望の受験予定と、募集要項の選抜方式が異なります。先に志望の方式を編集してください。');const id=gid||crypto.randomUUID();let docId=uploadDraft.documentId;if(uploadDraft.file){docId=crypto.randomUUID();await putDocument(docId,uploadDraft.file,uploadDraft.file.name);}const nextGuide={...g,...data,...(g.sourceKind==='official'?{userModifiedAt:new Date().toISOString(),reviewRequired:false,autoLink:true,pdfUrl:data.sourceUrl!==g.sourceUrl?'':(g.pdfUrl||''),examDates:data.examDate!==g.examDate?[]:(g.examDates||[]),examDateOptions:data.examDate!==g.examDate?[]:(g.examDateOptions||[]),noIndividualExam:data.examDate?false:!!g.noIndividualExam,fieldSources:{},publicationStatus:'manual_verified'}:{}),id,documentId:docId,excerpt:$('#guideline-text').value,verifiedAt:new Date().toISOString()};try{commit(st=>{st.guidelines=st.guidelines.filter(x=>x.id!==id).concat(nextGuide);for(const student of st.students)for(const choice of student.choices)if(choice.guideId===id&&!isGuideCompatible(choice,nextGuide)){choice.guideId='';choice.officialLinkDismissed=true;}for(const student of st.students)for(const choice of student.choices)for(const a of additionalAdmissions(choice))if(a.guideId===id&&!isGuideCompatible({...choice,selectionType:a.selectionType},nextGuide))a.guideId='';if(context)st.students.find(s=>s.id===context.sid).choices.find(c=>c.rank===Number(context.rank)).guideId=id;});}catch(error){if(docId!==g.documentId)await cleanDocument(docId);throw error;}await cleanDocument(g.documentId);uploadDraft=null;shell();openGuide(id,context);notify('募集要項を保存しました');});
 const submitGuide=form.onsubmit;form.onsubmit=async e=>{e.preventDefault();if(uploadDraft?.busy||uploadDraft?.saving)return;const draft=uploadDraft,button=$('#save-guide');draft.saving=true;button.disabled=true;try{await submitGuide(e);}finally{if(uploadDraft===draft)draft.saving=false;if(button.isConnected)button.disabled=false;}};
 if($('#delete-guide'))$('#delete-guide').onclick=guard(async()=>{if(!confirm('この募集要項を削除しますか？生徒とのひも付けも解除されます。'))return;commit(st=>{if(g.sourceKind==='official')st.suppressedOfficialIds=[...new Set([...(st.suppressedOfficialIds||[]),gid])];st.guidelines=st.guidelines.filter(x=>x.id!==gid);st.students.forEach(s=>s.choices.forEach(c=>{if(c.guideId===gid)delete c.guideId;for(const a of additionalAdmissions(c))if(a.guideId===gid)a.guideId='';}));});await cleanDocument(g.documentId);uploadDraft=null;closeDrawer();shell();notify('募集要項を削除しました');});
}
function download(content,filename,type){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function exportCSV(){const columns=['組','番号','氏名',...Array.from({length:8},(_,i)=>[`第${i+1}志望コード`,`第${i+1}志望大学`,`第${i+1}志望学部`,`第${i+1}志望学科`,`第${i+1}志望方式`,`第${i+1}志望選抜区分`,`第${i+1}志望追加方式`,`第${i+1}志望日程`,`第${i+1}志望原文`]).flat()];const rows=state.students.map(s=>['3A',s.number,name(s),...Array.from({length:8},(_,i)=>{const c=s.choices.find(x=>x.rank===i+1);return [c?.code,c?.university,c?.faculty,c?.department,c?.method,c?selectionLabel(selectionTypeOf(c)):'',additionalAdmissions(c).map(a=>selectionLabel(a.selectionType)+'：'+a.method).join(' / '),c?.schedule,c?.rawName];}).flat()]);const protect=v=>{const s=String(v??'');return /^[=+@\-\t\r]/.test(s)?"'"+s:s;};const csv=[columns,...rows].map(row=>row.map(v=>'"'+protect(v).replaceAll('"','""')+'"').join(',')).join('\r\n');download('\ufeff'+csv,`3A志望校一覧_${today()}.csv`,'text/csv;charset=utf-8');notify('志望校一覧をCSV保存しました。復元にはJSONバックアップをご利用ください。');}
$('#csv-file').onchange=guard(async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;const bytes=await file.arrayBuffer();let text=new TextDecoder('utf-8',{fatal:false}).decode(bytes);if(text.includes('\uFFFD'))text=new TextDecoder('shift_jis').decode(bytes);const imported=importStudentCSV(text);if(imported.students.length!==42)throw Error(`42人のCSVが必要です。読み込んだ人数：${imported.students.length}人`);drawer('CSVを更新','保存する前に人数・志望数を確認してください。',`<div class="info-box">生徒 ${imported.students.length} 人 / 志望 ${imported.students.flatMap(s=>s.choices).length} 件<br>現在：${allChoices().length} 件の志望</div><p style="line-height:2;font-size:12px">志望校はCSVの内容に更新します。今回指示で追加した志望は、CSVの同じ順位が空欄なら保持します。CSVに別の志望がある順位はCSVを優先します。入力した氏名と、同じ出席番号・順位・募集単位コードの要項ひも付け・追加方式を引き継ぎます。変更前の内容が必要な場合は、先にJSONバックアップを保存してください。</p>${(imported.warnings||[]).length?`<p class="info-box warning-box">${esc(imported.warnings.join('\n'))}</p>`:''}`,`<button class="btn" id="cancel-import">中止</button><button class="btn primary" id="confirm-import">42人の志望校を更新</button>`);$('#cancel-import').onclick=()=>closeDrawer();$('#confirm-import').onclick=guard(async()=>{commit(st=>{st.students=mergeImportedStudents(imported.students,st.students);});closeDrawer();shell();notify('42人の志望校を更新しました');});});
$('#backup-file').onchange=guard(async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>350*1024*1024)throw Error('バックアップが大きすぎます。');const backup=JSON.parse(await file.text());drawer('バックアップから復元','現在の内容を置き換えます。',`<p style="font-size:12px;line-height:2">${esc(file.name)} を読み込みました。現在の生徒・志望校・募集要項を、このバックアップの内容に置き換えます。</p><p class="footer-note">復元前にファイルを検証します。不正な形式のファイルは復元しません。</p>`,`<button class="btn" id="cancel-restore">中止</button><button class="btn primary" id="confirm-restore">復元する</button>`);$('#cancel-restore').onclick=()=>closeDrawer();$('#confirm-restore').onclick=guard(async()=>{const button=$('#confirm-restore');button.disabled=true;try{state=await restoreBackup(backup);if(seed?.officialRevision)persist(mergeOfficialSeed(state,seed));closeDrawer();shell();notify('バックアップから復元しました');}finally{if(button.isConnected)button.disabled=false;}});});
document.addEventListener('keydown',e=>{if(!$('#overlay').innerHTML)return;if(e.key==='Escape')closeDrawer();if(e.key==='Tab'){const items=[...$('#overlay').querySelectorAll('button:not([disabled]),a[href],input:not([hidden]),select,textarea')].filter(el=>el.offsetParent!==null);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('beforeunload',e=>{if(uploadDraft?.dirty){e.preventDefault();e.returnValue='';}});
try{seed=JSON.parse(document.getElementById('initial-seed').textContent);state=await loadState(seed);shell();}catch(e){$('#app').innerHTML=`<div class="error-screen"><h2>データを開けませんでした</h2><p>${esc(e.message)}</p><p>ブラウザの保存領域を有効にして再読み込みしてください。保存済みデータは自動で上書きしません。</p><button class="btn" id="retry">再読み込み</button> <button class="btn" id="recover">バックアップから復元</button></div>`;$('#retry').onclick=()=>location.reload();$('#recover').onclick=()=>$('#backup-file').click();}
